def yearfrac(t0, t1):
    return (t1 - t0).days / 365.0


def bond_cashflows(c, T, f=2):
    times = np.arange(1 / f, T + 1e-9, 1 / f)
    cfs = np.full_like(times, c / f, dtype=float)
    cfs[-1] += 1.0
    return times, cfs


def make_synthetic_bond(issue_date, maturity_years, coupon, units=0.0, f=2):
    times, cfs = bond_cashflows(coupon, maturity_years, f=f)
    payment_dates = pd.to_datetime(
        [issue_date + pd.DateOffset(months=int(round(12 * t))) for t in times]
    )
    return {
        "issue_date": pd.Timestamp(issue_date),
        "original_maturity": float(maturity_years),
        "coupon": float(coupon),
        "times": times.astype(float),
        "cfs": cfs.astype(float),
        "payment_dates": payment_dates,
        "units": float(units),
        "freq": int(f),
    }


def remaining_maturity(bond, valuation_date):
    if bond is None:
        return 0.0
    delta = yearfrac(bond["issue_date"], valuation_date)
    return float(max(bond["times"][-1] - delta, 0.0))


def get_current_par_yield(date, maturity):
    label = issue_labels[maturity]
    y = float(month_end_curve.loc[date, label])
    if not np.isfinite(y):
        raise ValueError(f"Missing par yield for {label} on {date}")
    return y

def curve_date_for(d):
    if d in df_dec.index:
        return d
    idx = df_dec.index.searchsorted(d, side="right") - 1
    if idx &lt; 0:
        return None
    return df_dec.index[idx]

def get_cash_rate(date, label=cash_tenor_label):
    curve_date = curve_date_for(date)
    if curve_date is None:
        return 0.0
    r = float(df_dec.loc[curve_date, label]) if label in df_dec.columns else np.nan
    if not np.isfinite(r):
        for fallback in ["3M", "6M", "1Y"]:
            if fallback in df_dec.columns:
                r = float(df_dec.loc[curve_date, fallback])
                if np.isfinite(r):
                    break
    return float(r) if np.isfinite(r) else 0.0


def grow_cash(cash, start_date, end_date):
    dt = yearfrac(start_date, end_date)
    r = get_cash_rate(start_date)
    return float(cash * math.exp(r * dt))

max_rebalance_gap_days = 45


def split_contiguous_blocks(dates, max_gap_days=max_rebalance_gap_days):
    dates = pd.DatetimeIndex(sorted(pd.to_datetime(dates).unique()))
    if len(dates) == 0:
        return []

    blocks = []
    start = 0
    for i in range(1, len(dates)):
        if (dates[i] - dates[i - 1]).days &gt; max_gap_days:
            blocks.append(dates[start:i])
            start = i
    blocks.append(dates[start:len(dates)])
    return [pd.DatetimeIndex(b) for b in blocks if len(b) &gt; 0]


def choose_backtest_block(dates, max_gap_days=max_rebalance_gap_days, min_len=60):
    blocks = split_contiguous_blocks(dates, max_gap_days=max_gap_days)
    if len(blocks) == 0:
        return pd.DatetimeIndex([])

    blocks = [b for b in blocks if len(b) &gt;= min_len]
    if len(blocks) == 0:
        return pd.DatetimeIndex([])

    return max(blocks, key=len)


def gap_safe_frame(obj, max_gap_days=max_rebalance_gap_days):
    out = obj.copy()

    if len(out.index) == 0:
        return out

    gap_mask = out.index.to_series().diff().dt.days.gt(max_gap_days)
    gap_dates = gap_mask[gap_mask].index

    if isinstance(out, pd.Series):
        out = out.astype(float)
        out.loc[gap_dates] = np.nan
    else:
        out = out.astype(float)
        out.loc[gap_dates, :] = np.nan

    return out

def price_bond(df_func, times, cfs, delta):
    mask = times &gt; delta + 1e-12
    if not np.any(mask):
        return 0.0
    t_rem = times[mask] - delta
    cf_rem = cfs[mask]
    return float(np.sum(cf_rem * df_func(t_rem)))


def remaining_cashflow_arrays(bond, valuation_date):
    if bond is None or bond.get("units", 0.0) &lt;= 0:
        return np.array([], dtype=float), np.array([], dtype=float)
    delta = yearfrac(bond["issue_date"], valuation_date)
    mask = bond["times"] &gt; delta + 1e-12
    if not np.any(mask):
        return np.array([], dtype=float), np.array([], dtype=float)
    t_rem = bond["times"][mask] - delta
    cf_rem = bond["cfs"][mask] * bond["units"]
    return t_rem, cf_rem

5) Expected return models for \(\mu_t\)
Min-Var models only try to optimize based on risk (Covariance) but Mean-Var and Max-Sharpe models need an expected-return vector \(\mu_t\). if we use an average of returns in a period, it can be noisy and the model will not generalize based on that. so we need a clear and stable estimation of \(\mu\) in each period and rebalance.
We compare three active expected-return models:

Momentum: a cross-sectional momentum signal scaled into annualized excess returns.
BayesStein: historical mean excess returns shrunk toward a stable Bayes-Stein prior.
BayesSteinMomentum: the same momentum direction as Momentum, then Bayes-Stein-style shrinkage toward a conservative scalar prior.


5.1 Lookback cumulative return
We pick a momentum lookback length \(H\) (like 6 months or 126 trading days) and then Define cumulative simple return for asset \(i\): \[
m_{t,i} = \prod_{\tau=t-H}^{t-1} (1+r_{\tau,i}) - 1
\]
(If you use log returns, you can equivalently use a sum of log returns.)


5.2 Cross-sectional standardization (z-score)
Momentum values are not comparable across time unless we standardize. We compute a cross-sectional z-score within the selected universe \(\mathcal{U}_t\):
If \(\bar{m}_t\) is the mean of \(m_{t,i}\) across \(i \in \mathcal{U}_t\), and \(s_t\) is the cross-sectional standard deviation. Define: \[
z_{t,i} = \frac{m_{t,i} - \bar{m}_t}{s_t}
\]
This makes \(z_{t,i}\) dimensionless and stable across different regimes.


5.3 Mapping the signal to expected returns
A common simple mapping is: \[
\mu_{t,i}^{(d)} = \kappa\, z_{t,i}
\]
Here \(\kappa\) is a scaling constant that controls the magnitude of expected returns.
Two main ways to calculate \(\kappa\):
(A) Target cross-sectional dispersion Choose a target daily standard deviation of expected returns, call it \(\sigma_\mu^{(d)}\), and set: \[
\kappa = \frac{\sigma_\mu^{(d)}}{\operatorname{std}(z_t)}
\]
(B) Target annual expected-return range If you want a typical annual spread of, say, \(\sigma_\mu^{(ann)}\), use: \[
\sigma_\mu^{(d)} = \frac{\sigma_\mu^{(ann)}}{252}
\] then we apply option (A) on \(\sigma_\mu^{(d)}\) to get to \(\kappa\).
This model is deliberately simple: it gives the optimizer a stable ranking signal without overfitting.

def momentum_score_from_returns(ret_window, mode="6-1"):
    R = ret_window.replace([np.inf, -np.inf], np.nan).dropna(how="any")
    T = len(R)
    if T &lt; 80:
        return R.mean().to_numpy(dtype=np.float64)

    if mode == "12-1":
        lookback, skip = 252, 21
    elif mode == "6-1":
        lookback, skip = 126, 21
    elif mode == "3-0":
        lookback, skip = 63, 0
    else:
        raise ValueError("Unknown momentum mode")

    if T &lt; lookback + skip + 5:
        lookback = min(lookback, max(63, T - skip - 1))

    R_use = R.iloc[-(lookback + skip):]
    R_mom = R_use.iloc[:-skip] if skip &gt; 0 else R_use
    return ((1.0 + R_mom).prod(axis=0) - 1.0).to_numpy(dtype=np.float64)


def winsorize_and_zscore(x, p_lo=0.05, p_hi=0.95):
    x = np.asarray(x, dtype=np.float64).flatten()
    if x.size == 0:
        return x

    finite = np.isfinite(x)
    if not finite.any():
        return np.zeros_like(x)

    fill_value = float(np.nanmedian(x[finite]))
    x = np.where(finite, x, fill_value)

    lo, hi = np.quantile(x, [p_lo, p_hi])
    x = np.clip(x, lo, hi)
    x = x - x.mean()

    sd = float(x.std())
    if sd &lt; 1e-12:
        return np.zeros_like(x)
    return x / sd


def scale_mu_to_target_sharpe(mu_dir, cov_ann, target_sharpe_ann, mu_cap_ann):
    mu = np.asarray(mu_dir, dtype=np.float64).flatten()
    if np.all(np.abs(mu) &lt; 1e-12):
        return np.zeros_like(mu)

    A = np.asarray(cov_ann, dtype=np.float64) + 1e-8 * np.eye(len(mu))
    try:
        x = np.linalg.solve(A, mu)
    except np.linalg.LinAlgError:
        x = np.linalg.lstsq(A, mu, rcond=None)[0]

    q = float(mu @ x)
    if (not np.isfinite(q)) or q &lt;= 1e-18:
        return np.zeros_like(mu)

    s = float(target_sharpe_ann) / np.sqrt(q)
    return np.clip(s * mu, -mu_cap_ann, mu_cap_ann)


def sample_mean_excess_ann_from_returns(ret_window, rf_daily):
    R = ret_window.replace([np.inf, -np.inf], np.nan).dropna(how="any")
    if R.shape[0] == 0:
        return np.zeros(R.shape[1], dtype=np.float64)

    mu_daily = R.mean(axis=0).to_numpy(dtype=np.float64) - float(rf_daily)
    return 252.0 * mu_daily


def build_scaled_mu_from_raw(raw_mu, cov_ann):
    mu_dir = winsorize_and_zscore(raw_mu, mu_winsor_lo, mu_winsor_hi)
    return scale_mu_to_target_sharpe(mu_dir, cov_ann, mu_target_sharpe_ann, mu_cap_ann)

